// Keep recognition events separate from the research labels and save final words only.
function createNoteDictation(Recognition:any, callbacks:any) {
  const recognition = new Recognition();
  recognition.lang = "en-US";
  recognition.continuous = true;
  recognition.interimResults = true;
  const finalIndexes = new Set<number>();
  let ended = false, stopping = false, failure = "", received = false;
  let limit:any = null, stopLimit:any = null;
  function finish() {
    if (ended) return;
    ended = true; clearTimeout(limit); clearTimeout(stopLimit);
    callbacks.onPreview("");
    callbacks.onEnd(failure || (received ? "Dictation added. You can edit the text below." : "No words were added. Try again or type your note."));
  }
  function cancel() {
    if (ended) return;
    finish();
    try { recognition.abort(); } catch {}
  }
  function stop() {
    if (ended || stopping) return;
    stopping = true; callbacks.onStatus("Finishing dictation…");
    try { stopLimit = setTimeout(cancel,5000); recognition.stop(); }
    catch { cancel(); }
  }
  recognition.onstart = () => { if (!ended && !stopping) callbacks.onStatus("Listening… speak your note or corrected video time."); };
  recognition.onresult = event => {
    if (ended) return;
    let preview = "";
    for (let i=0; i<event.results.length; i++) {
      const result = event.results[i];
      const words = String(result[0]?.transcript || "").trim();
      if (result.isFinal && !finalIndexes.has(i)) {
        finalIndexes.add(i);
        if (words) { received = true; callbacks.onFinal(words); }
      } else if (!result.isFinal && words) preview += (preview ? " " : "") + words;
    }
    callbacks.onPreview(preview);
  };
  recognition.onerror = event => {
    if (ended) return;
    failure = ({"not-allowed":"Microphone access was blocked. Allow the microphone for this review page, then try again.","service-not-allowed":"Speech recognition is unavailable here. Open the review page in Chrome, or use your device’s dictation in the notes field.","audio-capture":"No microphone was available. Check the microphone and try again.","network":"The speech service could not connect. Check your connection or type your note.","no-speech":"No speech was detected. Try again after pausing the game audio.","language-not-supported":"English dictation is unavailable in this browser. You can still type your note."})[event.error] || "Dictation stopped. Any words already added are kept.";
    cancel();
  };
  recognition.onend = finish;
  return {
    start() {
      callbacks.onStatus("Starting dictation… allow the microphone if prompted.");
      try { limit = setTimeout(stop,120000); recognition.start(); }
      catch { failure = "Dictation could not start. Try Chrome or use your device’s dictation in the notes field."; cancel(); }
    }, stop, cancel
  };
}

